when.set-body:
@{
								JObject body = context.Request.Body.As<JObject>(preserveContent: true);
								if (body["model"] != null) {
									body["model"] = context.Variables.GetValueOrDefault<string>("selectedDeployment", body["model"].ToString());
								}
								return body.ToString(Newtonsoft.Json.Formatting.None);
							}
